/* Halo's chat: near-monochrome and airy. Your prompt a soft gray bubble with no outline and large
   corners, cards barely there, links in the text's own color a step quieter.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own, so it reads over Halo and Halo Dark and over any theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-text) 7%, transparent);
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 22px;
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 3%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 8%, transparent);
  --cv-text: var(--agent-text);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 64%, transparent);
  --cv-link: color-mix(in srgb, var(--agent-text) 88%, var(--agent-page-bg));
  --agent-link: color-mix(in srgb, var(--agent-text) 88%, var(--agent-page-bg));
}

